const DENY = ['password', 'token'];

function logRequest(req) {
  log(JSON.stringify(req));                 // (1)
  const copy = req;                         // (2)
  for (const key of DENY) {
    if (copy.body[key]) copy.body[key] = '[redacted]';
  }
  log(JSON.stringify(copy));                // (3)
}
